<?php
declare(strict_types=1);
namespace App\Tests\Imperium\Runtime;
use App\Bootstrap\CanonicalJson; use App\Imperium\Runtime\Authorship\AuthorshipOfficeProvisioningService; use App\Imperium\Runtime\Authorship\CanonicalAuthorshipStaffRegistry; use PHPUnit\Framework\Attributes\DataProvider; use PHPUnit\Framework\TestCase;
final class AuthorshipOfficeProvisioningServiceTest extends TestCase { #[DataProvider('offices')] public function testOpensOneCanonicalResidentCaseSharedAcrossCommissionDemands(string $office, string $seat): void { $root = sys_get_temp_dir().'/imperium-'.$office.'-provisioning-'.bin2hex(random_bytes(6)); $dir = $root.'/var/imperium/mastermason/spawning-requests'; mkdir($dir, 0770, true); $service = new AuthorshipOfficeProvisioningService($root, new CanonicalAuthorshipStaffRegistry(dirname(__DIR__, 3))); $cases = []; for ($i=1;$i<=2;$i++) { $id=$office.'-activation-'.str_pad((string)$i,20,'0',STR_PAD_LEFT); $d=['demand_id'=>$id,'instance_id'=>'imperium-test','office'=>$office,'required_seats'=>[['seat'=>$seat]],'status'=>'CANONICAL_STAFF_ARTIFACTS_REQUIRED','authorship_authority'=>true,'authorship_authority_exercisable'=>false,'spawning_authority'=>false,'seat_binding_authority'=>false,'recipient_acceptance'=>false,'execution_authority'=>false]; $d['record_digest']=hash('sha256',CanonicalJson::encode($d)); file_put_contents($dir.'/'.$id.'.json',json_encode($d,JSON_THROW_ON_ERROR)); $cases[]=$service->open($office,$id); } try { self::assertSame($cases[0],$cases[1]); self::assertSame('CANONICAL_STAFF_READY',$cases[0]['status']); self::assertSame($seat,$cases[0]['seat']); self::assertTrue($cases[0]['authorship_authority']); self::assertFalse($cases[0]['authorship_authority_exercisable']); self::assertTrue($cases[0]['subordinate_staff_resolution_pending']); self::assertFalse($cases[0]['spawning_authority']); self::assertFalse($cases[0]['execution_authority']); } finally { $this->removeTree($root); } } public static function offices(): iterable { yield ['hagiography','hagiography.sanctographer']; yield ['studium','studium.chancellor']; } private function removeTree(string $path): void { if(!is_dir($path))return; foreach(array_diff(scandir($path)?:[],['.','..']) as $entry){$child=$path.'/'.$entry;is_dir($child)?$this->removeTree($child):unlink($child);}rmdir($path); } }
